package kz.bekzat.jwt.concurrency;
import kz.bekzat.jwt.service.RefreshTokenService;import org.springframework.stereotype.Component;import java.util.concurrent.*;
@Component public class RefreshRaceDemo {private final RefreshTokenService service;public RefreshRaceDemo(RefreshTokenService s){service=s;}public void runTwoRequests(String token)throws InterruptedException{CountDownLatch gate=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{for(int i=1;i<=2;i++){final int n=i;pool.submit(()->{try{gate.await();var r=service.rotate(token,"parallel-test","127.0.0.1");System.out.println("[THREAD-"+n+"] "+r.message());}catch(Exception e){System.out.println("[THREAD-"+n+"] "+e.getMessage());}});}gate.countDown();}finally{pool.shutdown();pool.awaitTermination(10,TimeUnit.SECONDS);}}}
